-- NEXO FORUM - complete schema for XAMPP/MySQL 8+
CREATE DATABASE IF NOT EXISTS nexo_forum CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE nexo_forum;
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) UNIQUE NOT NULL,email VARCHAR(120) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,avatar VARCHAR(255),bio TEXT,role ENUM('member','moderator','admin') DEFAULT 'member',status ENUM('active','inactive','banned') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS categories (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,slug VARCHAR(120) UNIQUE NOT NULL,description TEXT,icon VARCHAR(20),color VARCHAR(7) DEFAULT '#6be7ed',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS topics (id INT AUTO_INCREMENT PRIMARY KEY,category_id INT NOT NULL,user_id INT NOT NULL,title VARCHAR(255) NOT NULL,slug VARCHAR(255) UNIQUE NOT NULL,description TEXT,content LONGTEXT NOT NULL,views INT DEFAULT 0,replies INT DEFAULT 0,is_pinned TINYINT(1) DEFAULT 0,is_locked TINYINT(1) DEFAULT 0,is_approved TINYINT(1) DEFAULT 1,last_post_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS posts (id INT AUTO_INCREMENT PRIMARY KEY,topic_id INT NOT NULL,user_id INT NOT NULL,content LONGTEXT NOT NULL,likes INT DEFAULT 0,is_approved TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(topic_id) REFERENCES topics(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reports (id INT AUTO_INCREMENT PRIMARY KEY,reporter_id INT NOT NULL,topic_id INT NULL,post_id INT NULL,reason VARCHAR(100) NOT NULL,description TEXT,status ENUM('open','resolved','rejected') DEFAULT 'open',handled_by INT NULL,resolved_at TIMESTAMP NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS activity_log (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,action VARCHAR(100) NOT NULL,description TEXT,ip_address VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS notifications (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,type VARCHAR(30) NOT NULL,title VARCHAR(255) NOT NULL,link VARCHAR(255),is_read TINYINT(1) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
